from taf.collectors.core import StartableCommandCollector
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class JournalCollector(StartableCommandCollector):
    """
          To Start , Stop and Collect  journal logs on given configuration.
    """

    def __init__(self, options=None, journal_path=None, target_file_name=None, **kwargs):
        super(JournalCollector, self).__init__(**kwargs)
        self._log_path = "/tmp/journal_{name}.log".format(
            name=self._name)
        if journal_path is None:
            journal_path = "journal"
        self._journal_path = journal_path
        if target_file_name is None:
            self._target_file_name = "journal.log"
        else:
            self._target_file_name = target_file_name
        if options is None:
            options = "-o json"
        self._options = "{options} ".format(options=options) if options else ""
        self._sudo_prefix = None

    def _start(self):
        self._start_datetime = self._tool_executor.execute(b"date \'+%Y-%m-%d %H:%M:%S\'").strip().decode()

    def _stop(self):
        self._stop_datetime = self._tool_executor.execute(b"date \'+%Y-%m-%d %H:%M:%S\'").strip().decode()

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._tool_executor.execute(
            "{sudo_prefix}rm -f '{log_path}'".format(sudo_prefix=self._sudo_prefix,
                                                     log_path=self._log_path).encode())

    def _collect(self, target_dir):
        self._tool_executor.execute(
            "{sudo_prefix}journalctl "
            "--since=\"{start_datetime}\" "
            "--until=\"{stop_datetime}\" "
            "{options}"
            "> \"{log_path}\"".format(
                sudo_prefix=self._sudo_prefix,
                options=self._options,
                start_datetime=self._start_datetime,
                stop_datetime=self._stop_datetime,
                log_path=self._log_path).encode())
        self._file_getter.get_file(
            source_path=self._log_path,
            target_path="{target_dir}/{target_file_name}".format(
                target_dir=target_dir,
                target_file_name=self._target_file_name))

    def _teardown(self):
        self._tool_executor.execute(
            "{sudo_prefix}rm '{log_path}'".format(sudo_prefix=self._sudo_prefix, log_path=self._log_path).encode())
